'use strict';
window.RepoAccount=(()=>{
let user=null,enabled=false,analyticsEnabled=false,ready=false,liked=new Set(),pending=new Set(),guest=new Set(),queue=[],sending=false,timer,initial=true;
try{guest=new Set(JSON.parse(localStorage.getItem('reposhelf.likes.guest.v1')||'[]').filter(x=>typeof x==='string'))}catch{}liked=new Set(guest);
const notify=()=>window.dispatchEvent(new Event('reposhelf-account'));
async function request(path,options={}){const response=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options,signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok){const error=new Error(data.error?.message||'This action could not be completed.');error.status=response.status;throw error}return data}
async function refresh(){try{const data=await request('/api/auth');enabled=data.enabled;analyticsEnabled=data.analyticsEnabled;user=data.user;if(user){const ids=new Set();let cursor;do{const page=await request('/api/collection'+(cursor?'?cursor='+encodeURIComponent(cursor):''));page.items.forEach(x=>ids.add(x.id));cursor=page.nextCursor}while(cursor);liked=ids}else liked=new Set(guest)}catch(e){if(initial){user=null;liked=new Set(guest)}else throw e}finally{initial=false;ready=true;notify()}if(analyticsEnabled&&!pageTracked){pageTracked=true;track('page_view')}}
let pageTracked=false;
async function toggle(id){if(pending.has(id))return;const was=liked.has(id);pending.add(id);was?liked.delete(id):liked.add(id);notify();try{if(user)await request('/api/collection',{method:was?'DELETE':'PUT',body:JSON.stringify({id})});else{guest=new Set(liked);try{localStorage.setItem('reposhelf.likes.guest.v1',JSON.stringify([...guest]))}catch{throw Error('Browser storage is unavailable. Sign in to save likes across devices.')}}}catch(e){was?liked.add(id):liked.delete(id);throw e}finally{pending.delete(id);notify()}}
async function importGuest(){if(!user)throw Error('Sign in first.');for(const id of guest)if(!liked.has(id)){await request('/api/collection',{method:'PUT',body:JSON.stringify({id})});liked.add(id)}guest.clear();try{localStorage.removeItem('reposhelf.likes.guest.v1')}catch{}notify()}
async function signout(){await request('/api/auth?action=signout',{method:'POST',body:'{}'});user=null;liked=new Set(guest);notify()}
function visitorSession(){let visitor,session;try{visitor=localStorage.getItem('reposhelf.analytics.visitor');if(!visitor){visitor=crypto.randomUUID();localStorage.setItem('reposhelf.analytics.visitor',visitor)}let saved=JSON.parse(sessionStorage.getItem('reposhelf.analytics.session')||'null');if(!saved||Date.now()-saved.last>1800000)saved={id:crypto.randomUUID()};saved.last=Date.now();sessionStorage.setItem('reposhelf.analytics.session',JSON.stringify(saved));session=saved.id}catch{visitor=fallbackVisitor;session=fallbackSession}return {visitor,session}}
const fallbackVisitor=crypto.randomUUID(),fallbackSession=crypto.randomUUID();
function track(kind,project){if(!analyticsEnabled||user?.admin||location.pathname==='/admin.html'||navigator.globalPrivacyControl||navigator.doNotTrack==='1')return;queue.push({id:crypto.randomUUID(),kind,...project?{project}:{}});if(queue.length>40)queue.splice(0,queue.length-40);clearTimeout(timer);timer=setTimeout(flush,500)}
async function flush(){if(sending||!queue.length)return;sending=true;const batch=queue.slice(0,10);try{const response=await fetch('/api/analytics',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({...visitorSession(),events:batch}),keepalive:true,signal:AbortSignal.timeout(10000)});if(response.ok||response.status<500)queue.splice(0,batch.length)}catch{}finally{sending=false;if(queue.length)timer=setTimeout(flush,5000)}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)void flush()});
refresh();
return {get user(){return user},get enabled(){return enabled},get ready(){return ready},get liked(){return new Set(liked)},get guestCount(){return guest.size},has:id=>liked.has(id),busy:id=>pending.has(id),toggle,refresh,signout,importGuest,request,track};
})();
